@startuml
class Student {
  +studentID : string
  +birthDate : date
  +birthCity : string
  +birthRegion : string
  +enrollmentYear : int
}

class Professor {
  +name : string
  +birthDate : date
  +birthCity : string
}

class Faculty {
  +name : string
  +type : string
}

class Course {
  +code : string
  +lectureHours : int
}

class Exam {
  +grade : float
}

Student "1..*" -- "1" Faculty : is enrolled in
Student "1" -- "*" Exam : passes
Exam "*" -- "1" Course : for
Professor "1..*" -- "*" Course : teaches
Course "*" -- "1" Faculty : belongs to
@enduml

